// Pure formatting demo. No AI claim, network access, or delivery.
// 纯整理演示：不调用模型、不联网、不发送。
const seen = new Set();
const articles = [];
let skipped = 0;
for (const item of $input.all()) {
  const row = item.json || {};
  const title = typeof row.title === 'string' ? row.title.trim() : '';
  const link = typeof row.link === 'string' ? row.link.trim() : '';
  if (!title || !/^https?:\/\/[^\s]+$/i.test(link)) { skipped++; continue; }
  if (seen.has(link)) continue;
  seen.add(link);
  articles.push({title, link, summary: String(row.summary || '').slice(0, 1500)});
  if (articles.length >= 20) break;
}
return [{json: {
  status: 'draft_requires_review',
  synthetic_demo: true,
  article_count: articles.length,
  skipped_invalid: skipped,
  articles,
  draft: articles.map((a, i) => `${i + 1}. ${a.title}\n${a.link}\n${a.summary}`).join('\n\n')
}}];
